{
  "faqs": [
    {
      "question": "Which currencies does Acme Pay support?",
      "answer": "Acme Pay supports USD, EUR, GBP, and INR."
    },
    {
      "question": "Why was my payment declined?",
      "answer": "Payments may be declined due to insufficient funds, incorrect card details, or security checks by the payment processor. Please verify your information and try again."
    },
    {
      "question": "How can I request a refund?",
      "answer": "Refunds can be requested within 30 days of purchase. Once approved, they will be issued within 2 business days, though it may take an additional 5-10 business days for your bank to process the refund."
    },
    {
      "question": "How do I reset my Multi-Factor Authentication (MFA)?",
      "answer": "You can reset your MFA from the Customer Portal under Account > Security > Reset MFA. If you're locked out, support will verify your identity and send a reset link that expires in 24 hours."
    },
    {
      "question": "What payment transaction records does Acme retain?",
      "answer": "Acme keeps payment transaction records for 7 years to ensure compliance and facilitate any necessary audits."
    },
    {
      "question": "Does Acme store my full card number?",
      "answer": "No, Acme never stores the full card number. Instead, cards are tokenized by the Payment Gateway for enhanced security."
    },
    {
      "question": "What happens if I stay inactive in the Customer Portal?",
      "answer": "Sessions in the Customer Portal will expire after 15 minutes of inactivity, and you will receive an error CP-401 if you attempt to perform actions after that."
    },
    {
      "question": "Can I receive notifications about my transactions?",
      "answer": "Yes, Acme Notify can send you email and SMS notifications regarding your transactions and account activities."
    },
    {
      "question": "How do I access my transaction history?",
      "answer": "You can view your transaction history through the Acme Account Portal under the relevant section for payments or billing."
    },
    {
      "question": "Is there a limit on my transactions?",
      "answer": "Transaction limits may vary based on your account type and payment method. Please refer to your account settings for specific limits."
    },
    {
      "question": "What should I do if I forgot my password?",
      "answer": "If you forgot your password, you can reset it through the login page by following the 'Forgot Password' instructions."
    },
    {
      "question": "How can I update my payment method?",
      "answer": "You can update your payment method in the Acme Account Portal under the payment settings section."
    },
    {
      "question": "What is Acme Billing Pro?",
      "answer": "Acme Billing Pro is a comprehensive tool that helps you manage invoices, recurring payments, and billing cycles efficiently."
    },
    {
      "question": "How does Acme FraudShield work?",
      "answer": "Acme FraudShield uses advanced algorithms to detect and prevent fraudulent transactions, ensuring the security of your payments."
    },
    {
      "question": "Can I integrate Acme Ledger API with my existing systems?",
      "answer": "Yes, Acme Ledger API is designed for easy integration with your existing systems, allowing for seamless financial management."
    }
  ]
}
